struct AsyncTask {
    struct promise_type {
        AsyncTask get_return_object() {
            return AsyncTask{std::coroutine_handle<promise_type>::from_promise(*this)};
        }
        std::suspend_never initial_suspend() noexcept { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }
        void return_void() noexcept {}
        void unhandled_exception() { std::terminate(); }
    };

    std::coroutine_handle<promise_type> handle;
    ~AsyncTask() {
        if (handle && handle.done()) handle.destroy();
    }
};

class TransactionManager {
public:
    TransactionManager(ConcurrentMVCCMap& map, AsyncLogEngine& wal)
        : map_(map), wal_(wal), global_tx_seq_(100) {}

    uint64_t begin_read_only_tx() {
        return global_tx_seq_.load(std::memory_order_acquire);
    }

    AsyncTask execute_transaction_async(
        std::vector<std::pair<uint64_t, std::vector<uint8_t>>> writes,
        std::vector<uint64_t> deletes,
        std::atomic<bool>& done_signal,
        std::atomic<bool>& aborted_signal) 
    {
        uint64_t read_ts = global_tx_seq_.load(std::memory_order_acquire);
        uint64_t tx_id = global_tx_seq_.fetch_add(1, std::memory_order_acq_rel);

        wal_.enqueue_record(tx_id, LogRecordType::TX_BEGIN, 0, {});

        // Process Writes
        for (const auto& [k, v] : writes) {
            int res = map_.write(k, tx_id, read_ts, v, false);
            if (res != 0) {
                // Abort transaction
                wal_.enqueue_record(tx_id, LogRecordType::TX_COMMIT, 0, {}); // Log abort boundary
                aborted_signal.store(true, std::memory_order_release);
                done_signal.store(true, std::memory_order_release);
                co_return;
            }
            wal_.enqueue_record(tx_id, LogRecordType::TX_UPDATE, k, v);
        }

        // Process Deletes
        for (uint64_t k : deletes) {
            int res = map_.write(k, tx_id, read_ts, {}, true);
            if (res != 0) {
                aborted_signal.store(true, std::memory_order_release);
                done_signal.store(true, std::memory_order_release);
                co_return;
            }
            wal_.enqueue_record(tx_id, LogRecordType::TX_DELETE, k, {});
        }

        // Commit Log Frame
        uint64_t commit_lsn = wal_.enqueue_record(tx_id, LogRecordType::TX_COMMIT, 0, {});

        // Coroutine asynchronous wait for direct I/O completion
        co_await wal_.wait_durable(commit_lsn);

        aborted_signal.store(false, std::memory_order_release);
        done_signal.store(true, std::memory_order_release);
    }

private:
    ConcurrentMVCCMap& map_;
    AsyncLogEngine& wal_;
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_tx_seq_;
};

