int main() {
    std::cout << "========================================================\n";
    std::cout << " NUMA-Aware MPMC Priority Work-Stealing Scheduler (EBR) \n";
    std::cout << "========================================================\n";

    const size_t num_threads = std::max(4u, std::thread::hardware_concurrency());
    runtime::Scheduler scheduler(num_threads);

    scheduler.start();
    std::cout << "[+] Scheduler active with " << scheduler.worker_count() << " worker threads.\n";

    constexpr size_t TOTAL_TASKS = 200'000;
    std::atomic<uint64_t> completed_critical{0};
    std::atomic<uint64_t> completed_high{0};
    std::atomic<uint64_t> completed_normal{0};
    std::atomic<uint64_t> completed_low{0};

    auto start_time = std::chrono::high_resolution_clock::now();

    // Spawn heterogeneous workloads with various priority distributions
    for (size_t i = 0; i < TOTAL_TASKS; ++i) {
        runtime::Priority prio;
        if (i % 20 == 0)      prio = runtime::Priority::Critical;
        else if (i % 5 == 0)  prio = runtime::Priority::High;
        else if (i % 2 == 0)  prio = runtime::Priority::Normal;
        else                  prio = runtime::Priority::Low;

        scheduler.schedule([prio, &completed_critical, &completed_high, &completed_normal, &completed_low]() {
            // Simulate variable compute micro-task
            volatile uint32_t dummy = 0;
            for (int k = 0; k < 50; ++k) {
                dummy += k;
            }
            (void)dummy;

            switch (prio) {
                case runtime::Priority::Critical: completed_critical.fetch_add(1, std::memory_order_relaxed); break;
                case runtime::Priority::High:     completed_high.fetch_add(1, std::memory_order_relaxed); break;
                case runtime::Priority::Normal:   completed_normal.fetch_add(1, std::memory_order_relaxed); break;
                case runtime::Priority::Low:      completed_low.fetch_add(1, std::memory_order_relaxed); break;
                default: break;
            }
        }, prio);
    }

    // Await completion
    uint64_t total_done = 0;
    while (total_done < TOTAL_TASKS) {
        total_done = completed_critical.load(std::memory_order_relaxed) +
                     completed_high.load(std::memory_order_relaxed) +
                     completed_normal.load(std::memory_order_relaxed) +
                     completed_low.load(std::memory_order_relaxed);
        std::this_thread::yield();
    }

    auto end_time = std::chrono::high_resolution_clock::now();
    auto duration_ms = std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time).count();

    std::cout << "[+] Processed " << total_done << " tasks in " << duration_ms << " ms.\n";
    std::cout << "    - Critical Tasks: " << completed_critical.load() << "\n";
    std::cout << "    - High Tasks:     " << completed_high.load() << "\n";
    std::cout << "    - Normal Tasks:   " << completed_normal.load() << "\n";
    std::cout << "    - Low Tasks:      " << completed_low.load() << "\n";
    std::cout << "    - Throughput:     " << (static_cast<double>(TOTAL_TASKS) / (duration_ms > 0 ? duration_ms : 1)) * 1000.0 << " tasks/sec\n";

    scheduler.stop();
    std::cout << "[+] Scheduler shutdown cleanly without deadlocks or leaks.\n";
    return 0;
}
